globalThis.OFFLINE_SPECIES={"1":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"A strange seed was\nplanted on its\nback at birth.\fThe plant sprouts\nand grows with\nthis POK\u00e9MON."}],"genera":[{"language":{"name":"en"},"genus":"Seed Pok\u00e9mon"}]},"2":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"When the bulb on\nits back grows\nlarge, it appears\fto lose the\nability to stand\non its hind legs."}],"genera":[{"language":{"name":"en"},"genus":"Seed Pok\u00e9mon"}]},"3":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"The plant blooms\nwhen it is\nabsorbing solar\fenergy. It stays\non the move to\nseek sunlight."}],"genera":[{"language":{"name":"en"},"genus":"Seed Pok\u00e9mon"}]},"4":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Obviously prefers\nhot places. When\nit rains, steam\fis said to spout\nfrom the tip of\nits tail."}],"genera":[{"language":{"name":"en"},"genus":"Lizard Pok\u00e9mon"}]},"5":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"When it swings\nits burning tail,\nit elevates the\ftemperature to\nunbearably high\nlevels."}],"genera":[{"language":{"name":"en"},"genus":"Flame Pok\u00e9mon"}]},"6":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Spits fire that\nis hot enough to\nmelt boulders.\fKnown to cause\nforest fires\nunintentionally."}],"genera":[{"language":{"name":"en"},"genus":"Flame Pok\u00e9mon"}]},"7":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"After birth, its\nback swells and\nhardens into a\fshell. Powerfully\nsprays foam from\nits mouth."}],"genera":[{"language":{"name":"en"},"genus":"Tiny Turtle Pok\u00e9mon"}]},"8":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Often hides in\nwater to stalk\nunwary prey. For\fswimming fast, it\nmoves its ears to\nmaintain balance."}],"genera":[{"language":{"name":"en"},"genus":"Turtle Pok\u00e9mon"}]},"9":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"A brutal POK\u00e9MON\nwith pressurized\nwater jets on its\fshell. They are\nused for high\nspeed tackles."}],"genera":[{"language":{"name":"en"},"genus":"Shellfish Pok\u00e9mon"}]},"10":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its short feet\nare tipped with\nsuction pads that\fenable it to\ntirelessly climb\nslopes and walls."}],"genera":[{"language":{"name":"en"},"genus":"Worm Pok\u00e9mon"}]},"11":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"This POK\u00e9MON is\nvulnerable to\nattack while its\fshell is soft,\nexposing its weak\nand tender body."}],"genera":[{"language":{"name":"en"},"genus":"Cocoon Pok\u00e9mon"}]},"12":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"In battle, it\nflaps its wings\nat high speed to\frelease highly\ntoxic dust into\nthe air."}],"genera":[{"language":{"name":"en"},"genus":"Butterfly Pok\u00e9mon"}]},"13":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Often found in\nforests, eating\nleaves.\fIt has a sharp\nvenomous stinger\non its head."}],"genera":[{"language":{"name":"en"},"genus":"Hairy Bug Pok\u00e9mon"}]},"14":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Almost incapable\nof moving, this\nPOK\u00e9MON can only\fharden its shell\nto protect itself\nfrom predators."}],"genera":[{"language":{"name":"en"},"genus":"Cocoon Pok\u00e9mon"}]},"15":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Flies at high\nspeed and attacks\nusing its large\fvenomous stingers\non its forelegs\nand tail."}],"genera":[{"language":{"name":"en"},"genus":"Poison Bee Pok\u00e9mon"}]},"16":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"A common sight in\nforests and woods.\nIt flaps its\fwings at ground\nlevel to kick up\nblinding sand."}],"genera":[{"language":{"name":"en"},"genus":"Tiny Bird Pok\u00e9mon"}]},"17":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Very protective\nof its sprawling\nterritorial area,\fthis POK\u00e9MON will\nfiercely peck at\nany intruder."}],"genera":[{"language":{"name":"en"},"genus":"Bird Pok\u00e9mon"}]},"18":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"When hunting, it\nskims the surface\nof water at high\fspeed to pick off\nunwary prey such\nas MAGIKARP."}],"genera":[{"language":{"name":"en"},"genus":"Bird Pok\u00e9mon"}]},"19":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Bites anything\nwhen it attacks.\nSmall and very\fquick, it is a\ncommon sight in\nmany places."}],"genera":[{"language":{"name":"en"},"genus":"Mouse Pok\u00e9mon"}]},"20":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It uses its whis\u00ad\nkers to maintain\nits balance.\fIt apparently\nslows down if\nthey are cut off."}],"genera":[{"language":{"name":"en"},"genus":"Mouse Pok\u00e9mon"}]},"21":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Eats bugs in\ngrassy areas. It\nhas to flap its\fshort wings at\nhigh speed to\nstay airborne."}],"genera":[{"language":{"name":"en"},"genus":"Tiny Bird Pok\u00e9mon"}]},"22":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"With its huge and\nmagnificent wings,\nit can keep aloft\fwithout ever\nhaving to land\nfor rest."}],"genera":[{"language":{"name":"en"},"genus":"Beak Pok\u00e9mon"}]},"23":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Moves silently\nand stealthily.\nEats the eggs of\fbirds, such as\nPIDGEY and\nSPEAROW, whole."}],"genera":[{"language":{"name":"en"},"genus":"Snake Pok\u00e9mon"}]},"24":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It is rumored that\nthe ferocious\nwarning markings\fon its belly\ndiffer from area\nto area."}],"genera":[{"language":{"name":"en"},"genus":"Cobra Pok\u00e9mon"}]},"25":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"When several of\nthese POK\u00e9MON\ngather, their\felectricity could\nbuild and cause\nlightning storms."}],"genera":[{"language":{"name":"en"},"genus":"Mouse Pok\u00e9mon"}]},"26":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its long tail\nserves as a\nground to protect\fitself from its\nown high voltage\npower."}],"genera":[{"language":{"name":"en"},"genus":"Mouse Pok\u00e9mon"}]},"27":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Burrows deep\nunderground in\narid locations\ffar from water.\nIt only emerges\nto hunt for food."}],"genera":[{"language":{"name":"en"},"genus":"Mouse Pok\u00e9mon"}]},"28":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Curls up into a\nspiny ball when\nthreatened. It\fcan roll while\ncurled up to\nattack or escape."}],"genera":[{"language":{"name":"en"},"genus":"Mouse Pok\u00e9mon"}]},"29":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Although small,\nits venomous\nbarbs render this\fPOK\u00e9MON dangerous.\nThe female has\nsmaller horns."}],"genera":[{"language":{"name":"en"},"genus":"Poison Pin Pok\u00e9mon"}]},"30":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"The female's horn\ndevelops slowly.\nPrefers physical\fattacks such as\nclawing and\nbiting."}],"genera":[{"language":{"name":"en"},"genus":"Poison Pin Pok\u00e9mon"}]},"31":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its hard scales\nprovide strong\nprotection. It\fuses its hefty\nbulk to execute\npowerful moves."}],"genera":[{"language":{"name":"en"},"genus":"Drill Pok\u00e9mon"}]},"32":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Stiffens its ears\nto sense danger.\nThe larger its\fhorns, the more\npowerful its\nsecreted venom."}],"genera":[{"language":{"name":"en"},"genus":"Poison Pin Pok\u00e9mon"}]},"33":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"An aggressive\nPOK\u00e9MON that is\nquick to attack.\fThe horn on its\nhead secretes a\npowerful venom."}],"genera":[{"language":{"name":"en"},"genus":"Poison Pin Pok\u00e9mon"}]},"34":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It uses its\npowerful tail in\nbattle to smash,\fconstrict, then\nbreak the prey's\nbones."}],"genera":[{"language":{"name":"en"},"genus":"Drill Pok\u00e9mon"}]},"35":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its magical and\ncute appeal has\nmany admirers.\fIt is rare and\nfound only in\ncertain areas."}],"genera":[{"language":{"name":"en"},"genus":"Fairy Pok\u00e9mon"}]},"36":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"A timid fairy\nPOK\u00e9MON that is\nrarely seen. It\fwill run and hide\nthe moment it\nsenses people."}],"genera":[{"language":{"name":"en"},"genus":"Fairy Pok\u00e9mon"}]},"37":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"At the time of\nbirth, it has\njust one tail.\fThe tail splits\nfrom its tip as\nit grows older."}],"genera":[{"language":{"name":"en"},"genus":"Fox Pok\u00e9mon"}]},"38":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Very smart and\nvery vengeful.\nGrabbing one of\fits many tails\ncould result in a\n1000-year curse."}],"genera":[{"language":{"name":"en"},"genus":"Fox Pok\u00e9mon"}]},"39":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"When its huge eyes\nlight up, it sings\na mysteriously\fsoothing melody\nthat lulls its\nenemies to sleep."}],"genera":[{"language":{"name":"en"},"genus":"Balloon Pok\u00e9mon"}]},"40":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"The body is soft\nand rubbery. When\nangered, it will\fsuck in air and\ninflate itself to\nan enormous size."}],"genera":[{"language":{"name":"en"},"genus":"Balloon Pok\u00e9mon"}]},"41":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Forms colonies in\nperpetually dark\nplaces. Uses\fultrasonic waves\nto identify and\napproach targets."}],"genera":[{"language":{"name":"en"},"genus":"Bat Pok\u00e9mon"}]},"42":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Once it strikes,\nit will not stop\ndraining energy\ffrom the victim\neven if it gets\ntoo heavy to fly."}],"genera":[{"language":{"name":"en"},"genus":"Bat Pok\u00e9mon"}]},"43":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"During the day,\nit keeps its face\nburied in the\fground. At night,\nit wanders around\nsowing its seeds."}],"genera":[{"language":{"name":"en"},"genus":"Weed Pok\u00e9mon"}]},"44":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"The fluid that\noozes from its\nmouth isn't drool.\fIt is a nectar\nthat is used to\nattract prey."}],"genera":[{"language":{"name":"en"},"genus":"Weed Pok\u00e9mon"}]},"45":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"The larger its\npetals, the more\ntoxic pollen it\fcontains. Its big\nhead is heavy and\nhard to hold up."}],"genera":[{"language":{"name":"en"},"genus":"Flower Pok\u00e9mon"}]},"46":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Burrows to suck\ntree roots. The\nmushrooms on its\fback grow by draw\u00ad\ning nutrients from\nthe bug host."}],"genera":[{"language":{"name":"en"},"genus":"Mushroom Pok\u00e9mon"}]},"47":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"A host-parasite\npair in which the\nparasite mushroom\fhas taken over the\nhost bug. Prefers\ndamp places."}],"genera":[{"language":{"name":"en"},"genus":"Mushroom Pok\u00e9mon"}]},"48":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Lives in the\nshadows of tall\ntrees where it\feats insects. It\nis attracted by\nlight at night."}],"genera":[{"language":{"name":"en"},"genus":"Insect Pok\u00e9mon"}]},"49":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"The dust-like\nscales covering\nits wings are\fcolor coded to\nindicate the kinds\nof poison it has."}],"genera":[{"language":{"name":"en"},"genus":"Poison Moth Pok\u00e9mon"}]},"50":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Lives about one\nyard underground\nwhere it feeds on\fplant roots. It\nsometimes appears\nabove ground."}],"genera":[{"language":{"name":"en"},"genus":"Mole Pok\u00e9mon"}]},"51":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"A team of DIGLETT\ntriplets.\nIt triggers huge\fearthquakes by\nburrowing 60 miles\nunderground."}],"genera":[{"language":{"name":"en"},"genus":"Mole Pok\u00e9mon"}]},"52":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Adores circular\nobjects. Wanders\nthe streets on a\fnightly basis to\nlook for dropped\nloose change."}],"genera":[{"language":{"name":"en"},"genus":"Scratch Cat Pok\u00e9mon"}]},"53":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Although its fur\nhas many admirers,\nit is tough to\fraise as a pet\nbecause of its\nfickle meanness."}],"genera":[{"language":{"name":"en"},"genus":"Classy Cat Pok\u00e9mon"}]},"54":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"While lulling its\nenemies with its\nvacant look, this\fwily POK\u00e9MON will\nuse psychokinetic\npowers."}],"genera":[{"language":{"name":"en"},"genus":"Duck Pok\u00e9mon"}]},"55":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Often seen swim\u00ad\nming elegantly by\nlake shores. It\fis often mistaken\nfor the Japanese\nmonster, Kappa."}],"genera":[{"language":{"name":"en"},"genus":"Duck Pok\u00e9mon"}]},"56":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Extremely quick to\nanger. It could\nbe docile one\fmoment then\nthrashing away\nthe next instant."}],"genera":[{"language":{"name":"en"},"genus":"Pig Monkey Pok\u00e9mon"}]},"57":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Always furious\nand tenacious to\nboot. It will not\fabandon chasing\nits quarry until\nit is caught."}],"genera":[{"language":{"name":"en"},"genus":"Pig Monkey Pok\u00e9mon"}]},"58":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Very protective\nof its territory.\nIt will bark and\fbite to repel\nintruders from\nits space."}],"genera":[{"language":{"name":"en"},"genus":"Puppy Pok\u00e9mon"}]},"59":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"A POK\u00e9MON that\nhas been admired\nsince the past\ffor its beauty.\nIt runs agilely\nas if on wings."}],"genera":[{"language":{"name":"en"},"genus":"Legendary Pok\u00e9mon"}]},"60":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its newly grown\nlegs prevent it\nfrom running. It\fappears to prefer\nswimming than\ntrying to stand."}],"genera":[{"language":{"name":"en"},"genus":"Tadpole Pok\u00e9mon"}]},"61":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Capable of living\nin or out of\nwater. When out\fof water, it\nsweats to keep\nits body slimy."}],"genera":[{"language":{"name":"en"},"genus":"Tadpole Pok\u00e9mon"}]},"62":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"An adept swimmer\nat both the front\ncrawl and breast\fstroke. Easily\novertakes the best\nhuman swimmers."}],"genera":[{"language":{"name":"en"},"genus":"Tadpole Pok\u00e9mon"}]},"63":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Using its ability\nto read minds, it\nwill identify\fimpending danger\nand TELEPORT to\nsafety."}],"genera":[{"language":{"name":"en"},"genus":"Psi Pok\u00e9mon"}]},"64":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It emits special\nalpha waves from\nits body that\finduce headaches\njust by being\nclose by."}],"genera":[{"language":{"name":"en"},"genus":"Psi Pok\u00e9mon"}]},"65":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its brain can out\u00ad\nperform a super\u00ad\ncomputer.\fIts intelligence\nquotient is said\nto be 5,000."}],"genera":[{"language":{"name":"en"},"genus":"Psi Pok\u00e9mon"}]},"66":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Loves to build\nits muscles.\nIt trains in all\fstyles of martial\narts to become\neven stronger."}],"genera":[{"language":{"name":"en"},"genus":"Superpower Pok\u00e9mon"}]},"67":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its muscular body\nis so powerful, it\nmust wear a power\fsave belt to be\nable to regulate\nits motions."}],"genera":[{"language":{"name":"en"},"genus":"Superpower Pok\u00e9mon"}]},"68":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Using its heavy\nmuscles, it throws\npowerful punches\fthat can send the\nvictim clear over\nthe horizon."}],"genera":[{"language":{"name":"en"},"genus":"Superpower Pok\u00e9mon"}]},"69":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"A carnivorous\nPOK\u00e9MON that traps\nand eats bugs.\fIt uses its root\nfeet to soak up\nneeded moisture."}],"genera":[{"language":{"name":"en"},"genus":"Flower Pok\u00e9mon"}]},"70":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It spits out\nPOISONPOWDER to\nimmobilize the\fenemy and then\nfinishes it with\na spray of ACID."}],"genera":[{"language":{"name":"en"},"genus":"Flycatcher Pok\u00e9mon"}]},"71":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Said to live in\nhuge colonies\ndeep in jungles,\falthough no one\nhas ever returned\nfrom there."}],"genera":[{"language":{"name":"en"},"genus":"Flycatcher Pok\u00e9mon"}]},"72":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Drifts in shallow\nseas. Anglers who\nhook them by\faccident are\noften punished by\nits stinging acid."}],"genera":[{"language":{"name":"en"},"genus":"Jellyfish Pok\u00e9mon"}]},"73":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"The tentacles are\nnormally kept\nshort. On hunts,\fthey are extended\nto ensnare and\nimmobilize prey."}],"genera":[{"language":{"name":"en"},"genus":"Jellyfish Pok\u00e9mon"}]},"74":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Found in fields\nand mountains.\nMistaking them\ffor boulders,\npeople often step\nor trip on them."}],"genera":[{"language":{"name":"en"},"genus":"Rock Pok\u00e9mon"}]},"75":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Rolls down slopes\nto move. It rolls\nover any obstacle\fwithout slowing\nor changing its\ndirection."}],"genera":[{"language":{"name":"en"},"genus":"Rock Pok\u00e9mon"}]},"76":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its boulder-like\nbody is extremely\nhard. It can\feasily withstand\ndynamite blasts\nwithout damage."}],"genera":[{"language":{"name":"en"},"genus":"Megaton Pok\u00e9mon"}]},"77":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its hooves are 10\ntimes harder than\ndiamonds. It can\ftrample anything\ncompletely flat\nin little time."}],"genera":[{"language":{"name":"en"},"genus":"Fire Horse Pok\u00e9mon"}]},"78":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Very competitive,\nthis POK\u00e9MON will\nchase anything\fthat moves fast\nin the hopes of\nracing it."}],"genera":[{"language":{"name":"en"},"genus":"Fire Horse Pok\u00e9mon"}]},"79":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Incredibly slow\nand dopey. It\ntakes 5 seconds\ffor it to feel\npain when under\nattack."}],"genera":[{"language":{"name":"en"},"genus":"Dopey Pok\u00e9mon"}]},"80":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"The SHELLDER that\nis latched onto\nSLOWPOKE's tail\fis said to feed\non the host's left\nover scraps."}],"genera":[{"language":{"name":"en"},"genus":"Hermit Crab Pok\u00e9mon"}]},"81":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Uses anti-gravity\nto stay suspended.\nAppears without\fwarning and uses\nTHUNDER WAVE and\nsimilar moves."}],"genera":[{"language":{"name":"en"},"genus":"Magnet Pok\u00e9mon"}]},"82":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Formed by several\nMAGNEMITEs linked\ntogether. They\ffrequently appear\nwhen sunspots\nflare up."}],"genera":[{"language":{"name":"en"},"genus":"Magnet Pok\u00e9mon"}]},"83":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"The sprig of\ngreen onions it\nholds is its\fweapon. It is\nused much like a\nmetal sword."}],"genera":[{"language":{"name":"en"},"genus":"Wild Duck Pok\u00e9mon"}]},"84":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"A bird that makes\nup for its poor\nflying with its\ffast foot speed.\nLeaves giant\nfootprints."}],"genera":[{"language":{"name":"en"},"genus":"Twin Bird Pok\u00e9mon"}]},"85":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Uses its three\nbrains to execute\ncomplex plans.\fWhile two heads\nsleep, one head\nstays awake."}],"genera":[{"language":{"name":"en"},"genus":"Triple Bird Pok\u00e9mon"}]},"86":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"The protruding\nhorn on its head\nis very hard.\fIt is used for\nbashing through\nthick ice."}],"genera":[{"language":{"name":"en"},"genus":"Sea Lion Pok\u00e9mon"}]},"87":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Stores thermal\nenergy in its\nbody. Swims at a\fsteady 8 knots\neven in intensely\ncold waters."}],"genera":[{"language":{"name":"en"},"genus":"Sea Lion Pok\u00e9mon"}]},"88":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Appears in filthy\nareas. Thrives by\nsucking up\fpolluted sludge\nthat is pumped\nout of factories."}],"genera":[{"language":{"name":"en"},"genus":"Sludge Pok\u00e9mon"}]},"89":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Thickly covered\nwith a filthy,\nvile sludge. It\fis so toxic, even\nits footprints\ncontain poison."}],"genera":[{"language":{"name":"en"},"genus":"Sludge Pok\u00e9mon"}]},"90":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its hard shell\nrepels any kind\nof attack.\fIt is vulnerable\nonly when its\nshell is open."}],"genera":[{"language":{"name":"en"},"genus":"Bivalve Pok\u00e9mon"}]},"91":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"When attacked, it\nlaunches its\nhorns in quick\fvolleys. Its\ninnards have\nnever been seen."}],"genera":[{"language":{"name":"en"},"genus":"Bivalve Pok\u00e9mon"}]},"92":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Almost invisible,\nthis gaseous\nPOK\u00e9MON cloaks\fthe target and\nputs it to sleep\nwithout notice."}],"genera":[{"language":{"name":"en"},"genus":"Gas Pok\u00e9mon"}]},"93":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Because of its\nability to slip\nthrough block\fwalls, it is said\nto be from an\u00ad\nother dimension."}],"genera":[{"language":{"name":"en"},"genus":"Gas Pok\u00e9mon"}]},"94":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Under a full moon,\nthis POK\u00e9MON\nlikes to mimic\fthe shadows of\npeople and laugh\nat their fright."}],"genera":[{"language":{"name":"en"},"genus":"Shadow Pok\u00e9mon"}]},"95":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"As it grows, the\nstone portions of\nits body harden\fto become similar\nto a diamond, but\ncolored black."}],"genera":[{"language":{"name":"en"},"genus":"Rock Snake Pok\u00e9mon"}]},"96":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Puts enemies to\nsleep then eats\ntheir dreams.\fOccasionally gets\nsick from eating\nbad dreams."}],"genera":[{"language":{"name":"en"},"genus":"Hypnosis Pok\u00e9mon"}]},"97":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"When it locks eyes\nwith an enemy, it\nwill use a mix of\fPSI moves such as\nHYPNOSIS and\nCONFUSION."}],"genera":[{"language":{"name":"en"},"genus":"Hypnosis Pok\u00e9mon"}]},"98":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its pincers are\nnot only powerful\nweapons, they are\fused for balance\nwhen walking\nsideways."}],"genera":[{"language":{"name":"en"},"genus":"River Crab Pok\u00e9mon"}]},"99":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"The large pincer\nhas 10000 hp of\ncrushing power.\fHowever, its huge\nsize makes it\nunwieldy to use."}],"genera":[{"language":{"name":"en"},"genus":"Pincer Pok\u00e9mon"}]},"100":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Usually found in\npower plants.\nEasily mistaken\ffor a POK\u00e9 BALL,\nthey have zapped\nmany people."}],"genera":[{"language":{"name":"en"},"genus":"Ball Pok\u00e9mon"}]},"101":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It stores electric\nenergy under very\nhigh pressure.\fIt often explodes\nwith little or no\nprovocation."}],"genera":[{"language":{"name":"en"},"genus":"Ball Pok\u00e9mon"}]},"102":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Often mistaken\nfor eggs.\nWhen disturbed,\fthey quickly\ngather and attack\nin swarms."}],"genera":[{"language":{"name":"en"},"genus":"Egg Pok\u00e9mon"}]},"103":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Legend has it that\non rare occasions,\none of its heads\fwill drop off and\ncontinue on as an\nEXEGGCUTE."}],"genera":[{"language":{"name":"en"},"genus":"Coconut Pok\u00e9mon"}]},"104":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Because it never\nremoves its skull\nhelmet, no one\fhas ever seen\nthis POK\u00e9MON's\nreal face."}],"genera":[{"language":{"name":"en"},"genus":"Lonely Pok\u00e9mon"}]},"105":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"The bone it holds\nis its key weapon.\nIt throws the\fbone skillfully\nlike a boomerang\nto KO targets."}],"genera":[{"language":{"name":"en"},"genus":"Bone Keeper Pok\u00e9mon"}]},"106":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"When in a hurry,\nits legs lengthen\nprogressively.\fIt runs smoothly\nwith extra long,\nloping strides."}],"genera":[{"language":{"name":"en"},"genus":"Kicking Pok\u00e9mon"}]},"107":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"While apparently\ndoing nothing, it\nfires punches in\flightning fast\nvolleys that are\nimpossible to see."}],"genera":[{"language":{"name":"en"},"genus":"Punching Pok\u00e9mon"}]},"108":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its tongue can be\nextended like a\nchameleon's. It\fleaves a tingling\nsensation when it\nlicks enemies."}],"genera":[{"language":{"name":"en"},"genus":"Licking Pok\u00e9mon"}]},"109":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Because it stores\nseveral kinds of\ntoxic gases in\fits body, it is\nprone to exploding\nwithout warning."}],"genera":[{"language":{"name":"en"},"genus":"Poison Gas Pok\u00e9mon"}]},"110":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Where two kinds\nof poison gases\nmeet, 2 KOFFINGs\fcan fuse into a\nWEEZING over many\nyears."}],"genera":[{"language":{"name":"en"},"genus":"Poison Gas Pok\u00e9mon"}]},"111":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its massive bones\nare 1000 times\nharder than human\fbones. It can\neasily knock a\ntrailer flying."}],"genera":[{"language":{"name":"en"},"genus":"Spikes Pok\u00e9mon"}]},"112":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Protected by an\narmor-like hide,\nit is capable of\fliving in molten\nlava of 3,600\ndegrees."}],"genera":[{"language":{"name":"en"},"genus":"Drill Pok\u00e9mon"}]},"113":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"A rare and elusive\nPOK\u00e9MON that is\nsaid to bring\fhappiness to those\nwho manage to get\nit."}],"genera":[{"language":{"name":"en"},"genus":"Egg Pok\u00e9mon"}]},"114":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"The whole body is\nswathed with wide\nvines that are\fsimilar to sea\u00ad\nweed. Its vines\nshake as it walks."}],"genera":[{"language":{"name":"en"},"genus":"Vine Pok\u00e9mon"}]},"115":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"The infant rarely\nventures out of\nits mother's\fprotective pouch\nuntil it is 3\nyears old."}],"genera":[{"language":{"name":"en"},"genus":"Parent Pok\u00e9mon"}]},"116":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Known to shoot\ndown flying bugs\nwith precision\fblasts of ink\nfrom the surface\nof the water."}],"genera":[{"language":{"name":"en"},"genus":"Dragon Pok\u00e9mon"}]},"117":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Capable of swim\u00ad\nming backwards by\nrapidly flapping\fits wing-like\npectoral fins and\nstout tail."}],"genera":[{"language":{"name":"en"},"genus":"Dragon Pok\u00e9mon"}]},"118":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its tail fin\nbillows like an\nelegant ballroom\fdress, giving it\nthe nickname of\nthe Water Queen."}],"genera":[{"language":{"name":"en"},"genus":"Goldfish Pok\u00e9mon"}]},"119":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"In the autumn\nspawning season,\nthey can be seen\fswimming power\u00ad\nfully up rivers\nand creeks."}],"genera":[{"language":{"name":"en"},"genus":"Goldfish Pok\u00e9mon"}]},"120":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"An enigmatic\nPOK\u00e9MON that can\neffortlessly\fregenerate any\nappendage it\nloses in battle."}],"genera":[{"language":{"name":"en"},"genus":"Star Shape Pok\u00e9mon"}]},"121":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its central core\nglows with the\nseven colors of\fthe rainbow. Some\npeople value the\ncore as a gem."}],"genera":[{"language":{"name":"en"},"genus":"Mysterious Pok\u00e9mon"}]},"122":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"If interrupted\nwhile it is\nmiming, it will\fslap around the\noffender with its\nbroad hands."}],"genera":[{"language":{"name":"en"},"genus":"Barrier Pok\u00e9mon"}]},"123":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"With ninja-like\nagility and speed,\nit can create the\fillusion that\nthere is more\nthan one."}],"genera":[{"language":{"name":"en"},"genus":"Mantis Pok\u00e9mon"}]},"124":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It seductively\nwiggles its hips\nas it walks. It\fcan cause people\nto dance in\nunison with it."}],"genera":[{"language":{"name":"en"},"genus":"Human Shape Pok\u00e9mon"}]},"125":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Normally found\nnear power plants,\nthey can wander\faway and cause\nmajor blackouts\nin cities."}],"genera":[{"language":{"name":"en"},"genus":"Electric Pok\u00e9mon"}]},"126":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its body always\nburns with an\norange glow that\fenables it to\nhide perfectly\namong flames."}],"genera":[{"language":{"name":"en"},"genus":"Spitfire Pok\u00e9mon"}]},"127":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"If it fails to\ncrush the victim\nin its pincers,\fit will swing it\naround and toss\nit hard."}],"genera":[{"language":{"name":"en"},"genus":"Stag Beetle Pok\u00e9mon"}]},"128":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"When it targets\nan enemy, it\ncharges furiously\fwhile whipping its\nbody with its\nlong tails."}],"genera":[{"language":{"name":"en"},"genus":"Wild Bull Pok\u00e9mon"}]},"129":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"In the distant\npast, it was\nsomewhat stronger\fthan the horribly\nweak descendants\nthat exist today."}],"genera":[{"language":{"name":"en"},"genus":"Fish Pok\u00e9mon"}]},"130":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Rarely seen in\nthe wild. Huge\nand vicious, it\fis capable of\ndestroying entire\ncities in a rage."}],"genera":[{"language":{"name":"en"},"genus":"Atrocious Pok\u00e9mon"}]},"131":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"A POK\u00e9MON that\nhas been over\u00ad\nhunted almost to\fextinction. It\ncan ferry people\nacross the water."}],"genera":[{"language":{"name":"en"},"genus":"Transport Pok\u00e9mon"}]},"132":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Capable of copying\nan enemy's genetic\ncode to instantly\ftransform itself\ninto a duplicate\nof the enemy."}],"genera":[{"language":{"name":"en"},"genus":"Transform Pok\u00e9mon"}]},"133":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its genetic code\nis irregular.\nIt may mutate if\fit is exposed to\nradiation from\nelement STONEs."}],"genera":[{"language":{"name":"en"},"genus":"Evolution Pok\u00e9mon"}]},"134":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Lives close to\nwater. Its long\ntail is ridged\fwith a fin which\nis often mistaken\nfor a mermaid's."}],"genera":[{"language":{"name":"en"},"genus":"Bubble Jet Pok\u00e9mon"}]},"135":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It accumulates\nnegative ions in\nthe atmosphere to\fblast out 10000-\nvolt lightning\nbolts."}],"genera":[{"language":{"name":"en"},"genus":"Lightning Pok\u00e9mon"}]},"136":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"When storing\nthermal energy in\nits body, its\ftemperature could\nsoar to over 1600\ndegrees."}],"genera":[{"language":{"name":"en"},"genus":"Flame Pok\u00e9mon"}]},"137":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"A POK\u00e9MON that\nconsists entirely\nof programming\fcode. Capable of\nmoving freely in\ncyberspace."}],"genera":[{"language":{"name":"en"},"genus":"Virtual Pok\u00e9mon"}]},"138":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Although long\nextinct, in rare\ncases, it can be\fgenetically\nresurrected from\nfossils."}],"genera":[{"language":{"name":"en"},"genus":"Spiral Pok\u00e9mon"}]},"139":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"A prehistoric\nPOK\u00e9MON that died\nout when its\fheavy shell made\nit impossible to\ncatch prey."}],"genera":[{"language":{"name":"en"},"genus":"Spiral Pok\u00e9mon"}]},"140":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"A POK\u00e9MON that\nwas resurrected\nfrom a fossil\ffound in what was\nonce the ocean\nfloor eons ago."}],"genera":[{"language":{"name":"en"},"genus":"Shellfish Pok\u00e9mon"}]},"141":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its sleek shape is\nperfect for swim\u00ad\nming. It slashes\fprey with its\nclaws and drains\nthe body fluids."}],"genera":[{"language":{"name":"en"},"genus":"Shellfish Pok\u00e9mon"}]},"142":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"A ferocious, pre\u00ad\nhistoric POK\u00e9MON\nthat goes for the\fenemy's throat\nwith its serrated\nsaw-like fangs."}],"genera":[{"language":{"name":"en"},"genus":"Fossil Pok\u00e9mon"}]},"143":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Very lazy. Just\neats and sleeps.\nAs its rotund\fbulk builds, it\nbecomes steadily\nmore slothful."}],"genera":[{"language":{"name":"en"},"genus":"Sleeping Pok\u00e9mon"}]},"144":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"A legendary bird\nPOK\u00e9MON that is\nsaid to appear to\fdoomed people who\nare lost in icy\nmountains."}],"genera":[{"language":{"name":"en"},"genus":"Freeze Pok\u00e9mon"}]},"145":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"A legendary bird\nPOK\u00e9MON that is\nsaid to appear\ffrom clouds while\ndropping enormous\nlightning bolts."}],"genera":[{"language":{"name":"en"},"genus":"Electric Pok\u00e9mon"}]},"146":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Known as the\nlegendary bird of\nfire. Every flap\fof its wings\ncreates a dazzling\nflash of flames."}],"genera":[{"language":{"name":"en"},"genus":"Flame Pok\u00e9mon"}]},"147":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Long considered a\nmythical POK\u00e9MON\nuntil recently\fwhen a small\ncolony was found\nliving underwater."}],"genera":[{"language":{"name":"en"},"genus":"Dragon Pok\u00e9mon"}]},"148":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"A mystical POK\u00e9MON\nthat exudes a\ngentle aura.\fHas the ability\nto change climate\nconditions."}],"genera":[{"language":{"name":"en"},"genus":"Dragon Pok\u00e9mon"}]},"149":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"An extremely\nrarely seen\nmarine POK\u00e9MON.\fIts intelligence\nis said to match\nthat of humans."}],"genera":[{"language":{"name":"en"},"genus":"Dragon Pok\u00e9mon"}]},"150":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It was created by\na scientist after\nyears of horrific\fgene splicing and\nDNA engineering\nexperiments."}],"genera":[{"language":{"name":"en"},"genus":"Genetic Pok\u00e9mon"}]},"151":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"So rare that it\nis still said to\nbe a mirage by\fmany experts. Only\na few people have\nseen it worldwide."}],"genera":[{"language":{"name":"en"},"genus":"New Species Pok\u00e9mon"}]},"152":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"A sweet aroma\ngently wafts from\nthe leaf on its\fhead. It is docile\nand loves to soak\nup the sun's rays."}],"genera":[{"language":{"name":"en"},"genus":"Leaf Pok\u00e9mon"}]},"153":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"The scent of\nspices comes from\naround its neck.\fSomehow, sniffing\nit makes you want\nto fight."}],"genera":[{"language":{"name":"en"},"genus":"Leaf Pok\u00e9mon"}]},"154":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"The aroma that\nrises from its\npetals contains a\fsubstance that\ncalms aggressive\nfeelings."}],"genera":[{"language":{"name":"en"},"genus":"Herb Pok\u00e9mon"}]},"155":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It is timid, and\nalways curls it\u00ad\nself up in a ball.\fIf attacked, it\nflares up its back\nfor protection."}],"genera":[{"language":{"name":"en"},"genus":"Fire Mouse Pok\u00e9mon"}]},"156":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Be careful if it\nturns its back\nduring battle. It\fmeans that it will\nattack with the\nfire on its back."}],"genera":[{"language":{"name":"en"},"genus":"Volcano Pok\u00e9mon"}]},"157":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"If its rage peaks,\nit becomes so hot\nthat anything that\ftouches it will\ninstantly go\nup in flames."}],"genera":[{"language":{"name":"en"},"genus":"Volcano Pok\u00e9mon"}]},"158":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its well-developed\njaws are powerful\nand capable of\fcrushing anything.\nEven its trainer\nmust be careful."}],"genera":[{"language":{"name":"en"},"genus":"Big Jaw Pok\u00e9mon"}]},"159":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"If it loses a\nfang, a new one\ngrows back in its\fplace. There are\nalways 48 fangs\nlining its mouth."}],"genera":[{"language":{"name":"en"},"genus":"Big Jaw Pok\u00e9mon"}]},"160":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"When it bites with\nits massive and\npowerful jaws, it\fshakes its head\nand savagely tears\nits victim up."}],"genera":[{"language":{"name":"en"},"genus":"Big Jaw Pok\u00e9mon"}]},"161":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"A very cautious\nPOK\u00e9MON, it raises\nitself up using\fits tail to get a\nbetter view of its\nsurroundings."}],"genera":[{"language":{"name":"en"},"genus":"Scout Pok\u00e9mon"}]},"162":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It makes a nest to\nsuit its long and\nskinny body. The\fnest is impossible\nfor other POK\u00e9MON\nto enter."}],"genera":[{"language":{"name":"en"},"genus":"Long Body Pok\u00e9mon"}]},"163":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It always stands\non one foot. It\nchanges feet so\ffast, the movement\ncan rarely be\nseen."}],"genera":[{"language":{"name":"en"},"genus":"Owl Pok\u00e9mon"}]},"164":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its eyes are\nspecially adapted.\nThey concentrate\feven faint light\nand enable it to\nsee in the dark."}],"genera":[{"language":{"name":"en"},"genus":"Owl Pok\u00e9mon"}]},"165":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It is very timid.\nIt will be afraid\nto move if it is\falone. But it will\nbe active if it is\nin a group."}],"genera":[{"language":{"name":"en"},"genus":"Five Star Pok\u00e9mon"}]},"166":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"When the stars\nflicker in the\nnight sky, it\fflutters about,\nscattering a\nglowing powder."}],"genera":[{"language":{"name":"en"},"genus":"Five Star Pok\u00e9mon"}]},"167":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It lies still in\nthe same pose for\ndays in its web,\fwaiting for its\nunsuspecting prey\nto wander close."}],"genera":[{"language":{"name":"en"},"genus":"String Spit Pok\u00e9mon"}]},"168":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It spins string\nnot only from its\nrear but also from\fits mouth. It is\nhard to tell which\nend is which."}],"genera":[{"language":{"name":"en"},"genus":"Long Leg Pok\u00e9mon"}]},"169":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It flies so si\u00ad\nlently through the\ndark on its four\fwings that it may\nnot be noticed\neven when nearby."}],"genera":[{"language":{"name":"en"},"genus":"Bat Pok\u00e9mon"}]},"170":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It shoots positive\nand negative elec\u00ad\ntricity between\fthe tips of its\ntwo antennae and\nzaps its enemies."}],"genera":[{"language":{"name":"en"},"genus":"Angler Pok\u00e9mon"}]},"171":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"The light it emits\nis so bright that\nit can illuminate\fthe sea's surface\nfrom a depth of\nover three miles."}],"genera":[{"language":{"name":"en"},"genus":"Light Pok\u00e9mon"}]},"172":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It is not yet\nskilled at storing\nelectricity.\fIt may send out a\njolt if amused\nor startled."}],"genera":[{"language":{"name":"en"},"genus":"Tiny Mouse Pok\u00e9mon"}]},"173":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Because of its\nunusual, star-like\nsilhouette, people\fbelieve that it\ncame here on\na meteor."}],"genera":[{"language":{"name":"en"},"genus":"Star Shape Pok\u00e9mon"}]},"174":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It has a very soft\nbody. If it starts\nto roll, it will\fbounce all over\nand be impossible\nto stop."}],"genera":[{"language":{"name":"en"},"genus":"Balloon Pok\u00e9mon"}]},"175":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"The shell seems to\nbe filled with\njoy. It is said\fthat it will share\ngood luck when\ntreated kindly."}],"genera":[{"language":{"name":"en"},"genus":"Spike Ball Pok\u00e9mon"}]},"176":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"They say that it\nwill appear before\nkindhearted, car\u00ad\fing people and\nshower them with\nhappiness."}],"genera":[{"language":{"name":"en"},"genus":"Happiness Pok\u00e9mon"}]},"177":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Because its wings\naren't yet fully\ngrown, it has to\fhop to get around.\nIt is always star\u00ad\ning at something."}],"genera":[{"language":{"name":"en"},"genus":"Tiny Bird Pok\u00e9mon"}]},"178":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"They say that it\nstays still and\nquiet because it\fis seeing both the\npast and future at\nthe same time."}],"genera":[{"language":{"name":"en"},"genus":"Mystic Pok\u00e9mon"}]},"179":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"If static elec\u00ad\ntricity builds in\nits body, its\ffleece doubles in\nvolume. Touching\nit will shock you."}],"genera":[{"language":{"name":"en"},"genus":"Wool Pok\u00e9mon"}]},"180":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"As a result of\nstoring too much\nelectricity, it\fdeveloped patches\nwhere even downy\nwool won't grow."}],"genera":[{"language":{"name":"en"},"genus":"Wool Pok\u00e9mon"}]},"181":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"The tail's tip\nshines brightly\nand can be seen\ffrom far away. It\nacts as a beacon\nfor lost people."}],"genera":[{"language":{"name":"en"},"genus":"Light Pok\u00e9mon"}]},"182":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"BELLOSSOM gather\nat times and\nappear to dance.\fThey say that the\ndance is a ritual\nto summon the sun."}],"genera":[{"language":{"name":"en"},"genus":"Flower Pok\u00e9mon"}]},"183":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"The tip of its\ntail, which con\u00ad\ntains oil that is\flighter than wa\u00ad\nter, lets it swim\nwithout drowning."}],"genera":[{"language":{"name":"en"},"genus":"Aqua Mouse Pok\u00e9mon"}]},"184":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"By keeping still\nand listening in\u00ad\ntently, it can\ftell what is in\neven wild, fast-\nmoving rivers."}],"genera":[{"language":{"name":"en"},"genus":"Aqua Rabbit Pok\u00e9mon"}]},"185":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Although it always\npretends to be a\ntree, its composi\u00ad\ftion appears to be\ncloser to a rock\nthan a plant."}],"genera":[{"language":{"name":"en"},"genus":"Imitation Pok\u00e9mon"}]},"186":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"If POLIWAG and\nPOLIWHIRL hear its\nechoing cry, they\frespond by gather\u00ad\ning from far and\nwide."}],"genera":[{"language":{"name":"en"},"genus":"Frog Pok\u00e9mon"}]},"187":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"To keep from being\nblown away by the\nwind, they gather\fin clusters. They\ndo enjoy gentle\nbreezes, though."}],"genera":[{"language":{"name":"en"},"genus":"Cottonweed Pok\u00e9mon"}]},"188":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"The bloom on top\nof its head opens\nand closes as the\ftemperature fluc\u00ad\ntuates up and\ndown."}],"genera":[{"language":{"name":"en"},"genus":"Cottonweed Pok\u00e9mon"}]},"189":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Once it catches\nthe wind, it deft\u00ad\nly controls its\fcotton-puff spores\nto float, even\naround the world."}],"genera":[{"language":{"name":"en"},"genus":"Cottonweed Pok\u00e9mon"}]},"190":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its tail is so\npowerful that it\ncan use it to grab\fa tree branch and\nhold itself up in\nthe air."}],"genera":[{"language":{"name":"en"},"genus":"Long Tail Pok\u00e9mon"}]},"191":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It may drop out of\nthe sky suddenly.\nIf attacked by a\fSPEAROW, it will\nviolently shake\nits leaves."}],"genera":[{"language":{"name":"en"},"genus":"Seed Pok\u00e9mon"}]},"192":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It converts sun\u00ad\nlight into energy.\nIn the darkness\fafter sunset, it\ncloses its petals\nand becomes still."}],"genera":[{"language":{"name":"en"},"genus":"Sun Pok\u00e9mon"}]},"193":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"If it flaps its\nwings really fast,\nit can generate\fshock waves that\nwill shatter win\u00ad\ndows in the area."}],"genera":[{"language":{"name":"en"},"genus":"Clear Wing Pok\u00e9mon"}]},"194":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"This POK\u00e9MON lives\nin cold water. It\nwill leave the\fwater to search\nfor food when it\ngets cold outside."}],"genera":[{"language":{"name":"en"},"genus":"Water Fish Pok\u00e9mon"}]},"195":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"This carefree\nPOK\u00e9MON has an\neasy-going nature.\fWhile swimming, it\nalways bumps into\nboat hulls."}],"genera":[{"language":{"name":"en"},"genus":"Water Fish Pok\u00e9mon"}]},"196":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It uses the fine\nhair that covers\nits body to sense\fair currents and\npredict its ene\u00ad\nmy's actions."}],"genera":[{"language":{"name":"en"},"genus":"Sun Pok\u00e9mon"}]},"197":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"When agitated,\nthis POK\u00e9MON pro\u00ad\ntects itself by\fspraying poisonous\nsweat from its\npores."}],"genera":[{"language":{"name":"en"},"genus":"Moonlight Pok\u00e9mon"}]},"198":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Feared and loathed\nby many, it is\nbelieved to bring\fmisfortune to all\nthose who see it\nat night."}],"genera":[{"language":{"name":"en"},"genus":"Darkness Pok\u00e9mon"}]},"199":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It has incredible\nintellect and in\u00ad\ntuition. Whatever\fthe situation, it\nremains calm and\ncollected."}],"genera":[{"language":{"name":"en"},"genus":"Royal Pok\u00e9mon"}]},"200":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It likes playing\nmischievous tricks\nsuch as screaming\fand wailing to\nstartle people at\nnight."}],"genera":[{"language":{"name":"en"},"genus":"Screech Pok\u00e9mon"}]},"201":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Their shapes look\nlike hieroglyphs\non ancient tab\u00ad\flets. It is said\nthat the two are\nsomehow related."}],"genera":[{"language":{"name":"en"},"genus":"Symbol Pok\u00e9mon"}]},"202":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It hates light and\nshock. If attack\u00ad\ned, it inflates\fits body to pump\nup its counter\u00ad\nstrike."}],"genera":[{"language":{"name":"en"},"genus":"Patient Pok\u00e9mon"}]},"203":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its tail has a\nsmall brain of its\nown. Beware! If\fyou get close, it\nmay react to your\nscent and bite."}],"genera":[{"language":{"name":"en"},"genus":"Long Neck Pok\u00e9mon"}]},"204":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It likes to make\nits shell thicker\nby adding layers\fof tree bark. The\nadditional weight\ndoesn't bother it."}],"genera":[{"language":{"name":"en"},"genus":"Bagworm Pok\u00e9mon"}]},"205":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its entire body is\nshielded by a\nsteel-hard shell.\fWhat lurks inside\nthe armor is a\ntotal mystery."}],"genera":[{"language":{"name":"en"},"genus":"Bagworm Pok\u00e9mon"}]},"206":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"When spotted, this\nPOK\u00e9MON escapes\nbackward by furi\u00ad\fously boring into\nthe ground with\nits tail."}],"genera":[{"language":{"name":"en"},"genus":"Land Snake Pok\u00e9mon"}]},"207":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It flies straight\nat its target's\nface then clamps\fdown on the star\u00ad\ntled victim to\ninject poison."}],"genera":[{"language":{"name":"en"},"genus":"Fly Scorpion Pok\u00e9mon"}]},"208":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its body has been\ncompressed deep\nunder the ground.\fAs a result, it is\neven harder than a\ndiamond."}],"genera":[{"language":{"name":"en"},"genus":"Iron Snake Pok\u00e9mon"}]},"209":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Although it looks\nfrightening, it is\nactually kind and\faffectionate. It\nis very popular\namong women."}],"genera":[{"language":{"name":"en"},"genus":"Fairy Pok\u00e9mon"}]},"210":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It is actually\ntimid and easily\nspooked. If at\u00ad\ftacked, it flails\nabout to fend off\nits attacker."}],"genera":[{"language":{"name":"en"},"genus":"Fairy Pok\u00e9mon"}]},"211":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"To fire its poison\nspikes, it must\ninflate its body\fby drinking over\n2.6 gallons of\nwater all at once."}],"genera":[{"language":{"name":"en"},"genus":"Balloon Pok\u00e9mon"}]},"212":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It swings its eye-\npatterned pincers\nup to scare its\ffoes. This makes\nit look like it\nhas three heads."}],"genera":[{"language":{"name":"en"},"genus":"Pincer Pok\u00e9mon"}]},"213":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"The BERRIES it\nstores in its\nvase-like shell\fdecompose and\nbecome a gooey\nliquid."}],"genera":[{"language":{"name":"en"},"genus":"Mold Pok\u00e9mon"}]},"214":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"This powerful\nPOK\u00e9MON thrusts\nits prized horn\funder its enemies\u2019\nbellies then lifts\nand throws them."}],"genera":[{"language":{"name":"en"},"genus":"Single Horn Pok\u00e9mon"}]},"215":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its paws conceal\nsharp claws. If\nattacked, it sud\u00ad\fdenly extends the\nclaws and startles\nits enemy."}],"genera":[{"language":{"name":"en"},"genus":"Sharp Claw Pok\u00e9mon"}]},"216":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"If it finds honey,\nits crescent mark\nglows. It always\flicks its paws\nbecause they are\nsoaked with honey."}],"genera":[{"language":{"name":"en"},"genus":"Little Bear Pok\u00e9mon"}]},"217":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Although it is a\ngood climber, it\nprefers to snap\ftrees with its\nforelegs and eat\nfallen BERRIES."}],"genera":[{"language":{"name":"en"},"genus":"Hibernator Pok\u00e9mon"}]},"218":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It never sleeps.\nIt has to keep\nmoving because if\fit stopped, its\nmagma body would\ncool and harden."}],"genera":[{"language":{"name":"en"},"genus":"Lava Pok\u00e9mon"}]},"219":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"The shell on its\nback is just skin\nthat has cooled\fand hardened. It\nbreaks easily with\na slight touch."}],"genera":[{"language":{"name":"en"},"genus":"Lava Pok\u00e9mon"}]},"220":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It rubs its snout\non the ground to\nfind and dig up\ffood. It sometimes\ndiscovers hot\nsprings."}],"genera":[{"language":{"name":"en"},"genus":"Pig Pok\u00e9mon"}]},"221":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Because the long\nhair all over its\nbody obscures its\fsight, it just\nkeeps charging\nrepeatedly."}],"genera":[{"language":{"name":"en"},"genus":"Swine Pok\u00e9mon"}]},"222":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It continuously\nsheds and grows.\nThe tip of its\fhead is prized as\na treasure for its\nbeauty."}],"genera":[{"language":{"name":"en"},"genus":"Coral Pok\u00e9mon"}]},"223":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It has superb ac\u00ad\ncuracy. The water\nit shoots out can\fstrike even moving\nprey from more\nthan 300 feet."}],"genera":[{"language":{"name":"en"},"genus":"Jet Pok\u00e9mon"}]},"224":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It traps enemies\nwith its suction-\ncupped tentacles\fthen smashes them\nwith its rock-hard\nhead."}],"genera":[{"language":{"name":"en"},"genus":"Jet Pok\u00e9mon"}]},"225":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It carries food\nall day long.\nThere are tales\fabout lost people\nwho were saved by\nthe food it had."}],"genera":[{"language":{"name":"en"},"genus":"Delivery Pok\u00e9mon"}]},"226":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"As it majestically\nswims, it doesn't\ncare if REMORAID\fattach to it for\nscavenging its\nleftovers."}],"genera":[{"language":{"name":"en"},"genus":"Kite Pok\u00e9mon"}]},"227":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its sturdy wings\nlook heavy, but\nthey are actually\fhollow and light,\nallowing it to fly\nfreely in the sky."}],"genera":[{"language":{"name":"en"},"genus":"Armor Bird Pok\u00e9mon"}]},"228":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It uses different\nkinds of cries for\ncommunicating with\fothers of its kind\nand for pursuing\nits prey."}],"genera":[{"language":{"name":"en"},"genus":"Dark Pok\u00e9mon"}]},"229":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"If you are burned\nby the flames it\nshoots from its\fmouth, the pain\nwill never go\naway."}],"genera":[{"language":{"name":"en"},"genus":"Dark Pok\u00e9mon"}]},"230":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It is said that it\nusually hides in\nunderwater caves.\fIt can create\nwhirlpools by\nyawning."}],"genera":[{"language":{"name":"en"},"genus":"Dragon Pok\u00e9mon"}]},"231":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It swings its long\nsnout around play\u00ad\nfully, but because\fit is so strong,\nthat can be dan\u00ad\ngerous."}],"genera":[{"language":{"name":"en"},"genus":"Long Nose Pok\u00e9mon"}]},"232":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It has sharp, hard\ntusks and a rugged\nhide. Its TACKLE\fis strong enough\nto knock down a\nhouse."}],"genera":[{"language":{"name":"en"},"genus":"Armor Pok\u00e9mon"}]},"233":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"This upgraded\nversion of PORYGON\nis designed for\fspace exploration.\nIt can't fly,\nthough."}],"genera":[{"language":{"name":"en"},"genus":"Virtual Pok\u00e9mon"}]},"234":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"The curved antlers\nsubtly change the\nflow of air to\fcreate a strange\nspace where real\u00ad\nity is distorted."}],"genera":[{"language":{"name":"en"},"genus":"Big Horn Pok\u00e9mon"}]},"235":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"A special fluid\noozes from the tip\nof its tail. It\fpaints the fluid\neverywhere to mark\nits territory."}],"genera":[{"language":{"name":"en"},"genus":"Painter Pok\u00e9mon"}]},"236":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It is always\nbursting with en\u00ad\nergy. To make it\u00ad\fself stronger, it\nkeeps on fighting\neven if it loses."}],"genera":[{"language":{"name":"en"},"genus":"Scuffle Pok\u00e9mon"}]},"237":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"If you become\nenchanted by its\nsmooth, elegant,\fdance-like kicks,\nyou may get\ndrilled hard."}],"genera":[{"language":{"name":"en"},"genus":"Handstand Pok\u00e9mon"}]},"238":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its lips are the\nmost sensitive\nparts on its body.\fIt always uses its\nlips first to\nexamine things."}],"genera":[{"language":{"name":"en"},"genus":"Kiss Pok\u00e9mon"}]},"239":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It rotates its\narms to generate\nelectricity, but\fit tires easily,\nso it charges up\nonly a little bit."}],"genera":[{"language":{"name":"en"},"genus":"Electric Pok\u00e9mon"}]},"240":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Each and every\ntime it inhales\nand exhales, hot\fembers dribble out\nof its mouth and\nnostrils."}],"genera":[{"language":{"name":"en"},"genus":"Live Coal Pok\u00e9mon"}]},"241":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its milk is packed\nwith nutrition,\nmaking it the\fultimate beverage\nfor the sick or\nweary."}],"genera":[{"language":{"name":"en"},"genus":"Milk Cow Pok\u00e9mon"}]},"242":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Anyone who takes\neven one bite of\nBLISSEY's egg be\u00ad\fcomes unfailingly\ncaring and pleas\u00ad\nant to everyone."}],"genera":[{"language":{"name":"en"},"genus":"Happiness Pok\u00e9mon"}]},"243":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"The rain clouds it\ncarries let it\nfire thunderbolts\fat will. They say\nthat it descended\nwith lightning."}],"genera":[{"language":{"name":"en"},"genus":"Thunder Pok\u00e9mon"}]},"244":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Volcanoes erupt\nwhen it barks. Un\u00ad\nable to restrain\fits extreme power,\nit races headlong\naround the land."}],"genera":[{"language":{"name":"en"},"genus":"Volcano Pok\u00e9mon"}]},"245":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Said to be the\nreincarnation of\nnorth winds, it\fcan instantly\npurify filthy,\nmurky water."}],"genera":[{"language":{"name":"en"},"genus":"Aurora Pok\u00e9mon"}]},"246":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It feeds on soil.\nAfter it has eaten\na large mountain,\fit will fall\nasleep so it can\ngrow."}],"genera":[{"language":{"name":"en"},"genus":"Rock Skin Pok\u00e9mon"}]},"247":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its shell is as\nhard as sheet\nrock, and it is\falso very strong.\nIts THRASHING can\ntopple a mountain."}],"genera":[{"language":{"name":"en"},"genus":"Hard Shell Pok\u00e9mon"}]},"248":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Its body can't be\nharmed by any sort\nof attack, so it\fis very eager to\nmake challenges\nagainst enemies."}],"genera":[{"language":{"name":"en"},"genus":"Armor Pok\u00e9mon"}]},"249":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"It is said that it\nquietly spends its\ntime deep at the\fbottom of the sea\nbecause its powers\nare too strong."}],"genera":[{"language":{"name":"en"},"genus":"Diving Pok\u00e9mon"}]},"250":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"Legends claim this\nPOK\u00e9MON flies the\nworld's skies con\u00ad\ftinuously on its\nmagnificent seven-\ncolored wings."}],"genera":[{"language":{"name":"en"},"genus":"Rainbow Pok\u00e9mon"}]},"251":{"flavor_text_entries":[{"language":{"name":"en"},"flavor_text":"This POK\u00e9MON wan\u00ad\nders across time.\nGrass and trees\fflourish in the\nforests in which\nit has appeared."}],"genera":[{"language":{"name":"en"},"genus":"Time Travel Pok\u00e9mon"}]}};
